# group by canonical service name using alias resolution
svc = [f for f in facts if f.get('type')=='service']
alias_map = {}
for f in svc:
    names = {f.get('subject').lower()}
    for a in (f.get('aliases') or []):
        names.add(a.lower())
    for n in names:
        alias_map[n] = f.get('subject')
print(alias_map.get('thumbnail-api'), alias_map.get('catalog-gateway'), alias_map.get('the thumbnail api'))

from collections import defaultdict
d = defaultdict(set)
for f in inc:
    v = (f.get('affected_service') or f.get('subject'))
    d[alias_map.get(v.lower(), v.lower())].add(v)
counts = {k: sum(1 for f in inc if alias_map.get((f.get('affected_service') or f.get('subject')).lower(), (f.get('affected_service') or f.get('subject')).lower())==k) for k in d}
for k,v in sorted(counts.items(), key=lambda x:-x[1])[:6]:
    print(k, v, d[k])

